namespace LaTerzaCampana.Core;

public static class OriginNarrative69
{
    public sealed record Beat(string Speaker,string Text);
    public sealed record Reply(string Label,string Text,int Body=0,int Mind=0,int Hunger=0,string? Item=null,int Quantity=0);
    public sealed record Scene(Beat[] Opening,string[] Reactions,string FollowSpeaker,string FollowQuestion,Reply[] Replies,string Bridge);
    public static Scene Get(HeroId hero,int chapter)=>(hero,chapter) switch {
        (HeroId.Gladia,0)=>new([new("NARRATORE","L'inverno aveva svuotato le dispense del quartiere. Gladia percorreva il vicolo ogni mattina, prima che aprissero le botteghe."),new("MADRE","Perdonami, Gladia. Ieri le ho dato l'ultimo pezzo di pane. Non so più cosa inventarmi."),new("BAMBINA","Mamma dice che oggi mangeremo. È vero?"),new("GLADIA","Vediamo cosa posso fare. Ho ancora una visita da fare prima di sera.")], ["La bambina mangia in fretta. La madre ti mette in mano un sacchetto di erbe: è tutto ciò che possiede.","La madre comprende il tuo rifiuto, ma non riesce a nascondere la delusione.","La madre divide le provviste con la figlia. Ti ringrazia senza offrirti nulla in cambio.","La bambina ti chiama ancora una volta. Poi il vicolo torna silenzioso."],"MADRE","C'è una donna malata poco più avanti. Se passi da lei, dille che la ricordo ancora.",[new("Ascolta la madre","Ti racconta della vicina. Rimani più a lungo del previsto.",Hunger:-4),new("Prometti di farle visita","Le prometti che porterai il suo saluto."),new("Congedati","Ti congedi. Hai ancora una lunga giornata davanti.")],"Poco dopo, nella casa della donna malata, l'aria sa di febbre e cera."),
        (HeroId.Gladia,1)=>new([new("NARRATORE","La stanza era rimasta chiusa per giorni. Sul comodino si accumulavano tazze d'acqua ormai fredde."),new("MALATA","Gladia? Credevo che non sarebbe venuto più nessuno."),new("GLADIA","Da quanto tempo hai la febbre? Lascia che ti cambi le bende."),new("MALATA","Non ho nulla con cui pagarti. E non riesco più nemmeno a dormire.")], ["La donna respira meglio. Ti porge le ultime bende pulite, mentre senti le forze abbandonarti.","Il calore del rito le distende il volto. Sul tavolo è rimasto un infuso che puoi portare con te.","Vegli inutilmente per ore. La febbre non scende; nessuna delle tue preghiere sembra arrivare a destinazione."],"MALATA","Quando chiudo gli occhi sento qualcuno parlare. Tu lo senti, Gladia?",[new("Resta ancora con lei","Le tieni la mano finché si addormenta. Sei esausta.",Body:-4,Hunger:-3),new("Recita una preghiera","Preghi piano. Una voce sconosciuta ride, ma la donna non sembra udirla."),new("Cerca altro aiuto","Bussi alle porte vicine. Nessuno risponde.",Mind:-3)],"A notte fonda Gladia raggiunge la legnaia. La voce che aveva cercato di ignorare torna a parlarle."),
        (HeroId.Gladia,2)=>new([new("NARRATORE","Gladia si era rifugiata davanti al braciere. Le parole udite durante il giorno non appartenevano alla donna malata."),new("BRAKA","Quante vite hai salvato oggi? Quante ne salverai domani?"),new("GLADIA","Non sono affari tuoi."),new("BRAKA","Eppure sono dentro di te da prima del tuo primo respiro. Posso darti una forza che nessuna preghiera ti concederà.")], ["Un fremito ti percorre le dita. Per la prima volta riconosci il potere che Braka ti offre.","Stringi il medaglione. La voce arretra, senza svanire del tutto.","La tua sfida viene accolta da una risata. Il dolore ti piega le ginocchia.","Non rispondi. Il fuoco si spegne e la voce tace."],"BRAKA","Parti pure. Verrà il giorno in cui dovrai scegliere chi non salvare.",[],"Tempo dopo, un viaggio verso Dùsterbedragna le offre una via di fuga. Braka parte con lei."),
        (HeroId.Ambrosh,0)=>new([new("NARRATORE","La famiglia di Ambrosh aveva interpretato la sua nascita come un segno della dea. Anni dopo, ogni giorno era ancora governato da quella promessa."),new("TUTORE","Il santuario ha mandato un altro invito. Ti considerano una benedizione vivente."),new("AMBROSH","Non voglio trascorrere la vita sotto gli occhi di chi mi venera."),new("TUTORE","Capisco. Ma prima di partire dovrai imparare a convivere con ciò che Nuwdanìe ti ha imposto.")], ["Il tutore apre il libro e ti insegna un rito. Ti lascia anche un infuso per il viaggio.","Il tutore esita, poi ti mette in mano delle provviste. Non sa più come trattenerti.","Il libro resta chiuso. Nessuno trova le parole per proseguire."],"TUTORE","Se dovessi avere un'altra crisi lontano da casa, cosa farai?",[new("Rifiuta ogni giuramento","Non accetti di promettere obbedienza."),new("Prometti di chiedere aiuto","Prometti di non affrontare tutto da solo."),new("Fingi di acconsentire","Dici ciò che il tutore vuole sentire. La menzogna ti pesa.",Mind:-3)],"Più tardi, nella sua stanza, Ambrosh prepara ciò che porterà con sé."),
        (HeroId.Ambrosh,1)=>new([new("NARRATORE","Le crisi non erano una scelta. Quando il potere di Nuwdanìe si manifestava, perfino gli oggetti della stanza sembravano deformarsi in allusioni oscene."),new("AMBROSH","Basta. Non voglio che ogni pensiero venga ricondotto a questo."),new("FAMILIARE","Il guaritore ha lasciato dei rimedi. Possiamo anche ripetere il rito di respirazione."),new("AMBROSH","Devo imparare a vivere senza che siano gli altri a decidere per me.")], ["Ripeti il rito finché il respiro rallenta. Metti da parte una benda per il viaggio.","Raccogli le erbe e gli infusi. Il guaritore ti ha spiegato come usarli.","Aspetti che la crisi passi senza aiuto. Ti lascia sfinito e disorientato.","Esci dalla stanza, ma le visioni non spariscono con la distanza."],"AMBROSH","Domani partirò. Prima, devo decidere cosa lasciare qui.",[new("Cerca un momento di quiete","Rimani seduto in silenzio. Non accade altro."),new("Scrivi una nota per il viaggio","Annoti ciò che ti aiuta a distinguere i tuoi pensieri dai deliri.",Mind:2),new("Rinuncia a un infuso","Se ne hai uno, lo lasci sul tavolo.",Item:"infuso",Quantity:-1)],"Prima della partenza, Ambrosh visita un'ultima volta il giardino votivo."),
        (HeroId.Ambrosh,2)=>new([new("NARRATORE","Nel giardino le radici avevano spaccato la pietra. Fiori nuovi crescevano persino sulle statue consumate."),new("NUWDANÌE","Figlio mio. Perché continui a chiamare maledizione ciò che gli altri chiamano dono?"),new("AMBROSH","Perché sono io a sopportarne il peso, non loro."),new("NUWDANÌE","Allora decidi tu se portare con te la mia forza, oppure chiudermi fuori.")], ["I fiori si aprono all'unisono. Il potere della dea cresce in te, insieme alla paura di perderne il controllo.","Il medaglione diventa freddo. Per un istante i tuoi pensieri sono soltanto tuoi.","Non rispondi. I petali cadono ai tuoi piedi."],"NUWDANÌE","La mia voce saprà ritrovarti, ovunque tu vada.",[],"Ambrosh lascia la casa di famiglia. Il viaggio verso Dùsterbedragna è il primo che ha scelto da sé."),
        (HeroId.Roderick,0)=>new([new("COMMILITONE","Roderick? Ti ho chiamato tre volte. Da quando sei tornato dal fronte, fai spesso così."),new("RODERICK","Dietro di te... c'è un corridoio. Non c'era un momento fa."),new("COMMILITONE","Dietro di me c'è soltanto la libreria. Guardami. Siamo a casa, la guerra è finita."),new("RODERICK","Lo so. È proprio questo che mi spaventa. Non riconosco più il confine fra ciò che ricordo e ciò che vedo.")], ["La stanza si allunga oltre il muro. Il commilitone ti afferra la spalla e ti porge un infuso.","Ripeti i nomi dei compagni. La stanza torna stabile. L'uomo ti lascia le bende da campo.","Le pagine bruciano. Il corridoio scompare, ma il ricordo resta."],"COMMILITONE","Non devi raccontarmi tutto. Vuoi che resti ancora un po'?",[new("Racconta la visione","Ti ascolta senza capire. Tu stesso inizi a dubitare di ciò che hai visto.",Mind:-3),new("Chiedigli di restare","Resta accanto a te finché la stanza torna familiare."),new("Resta a riflettere","Rimani sveglio fino a tardi. Salti la cena.",Hunger:-3)],"Giorni dopo, un rumore nel cortile interrompe il riposo di Roderick."),
        (HeroId.Roderick,1)=>new([new("NARRATORE","Una creatura si era rifugiata tra le gabbie del cortile. Roderick non riusciva a riconoscerne la specie."),new("RODERICK","Non ti avvicinerò. Non se non vuoi."),new("NYARLATOTH","Ascolta meglio. Non hai forse riconosciuto la sua paura?"),new("RODERICK","Posso sentirla. Ma non so se è davvero sua o se sei tu a farmela sentire.")], ["La creatura abbassa il capo. Comprendi il principio del patto, senza obbligarla a seguirti.","Una presenza risponde al richiamo. Impari a mantenerla per qualche istante oltre il velo.","La creatura fugge attraverso il passaggio. Il cortile resta vuoto.","Le sbarre vibrano mentre ti allontani. Il terrore non si attenua."],"RODERICK","Non so ancora cosa sia successo. Devo rifletterci prima di fare un altro passo.",[new("Lascia spazio alla creatura","Non cerchi di costringerla ad avvicinarsi."),new("Osserva ancora","Aspetti a lungo. La fame aumenta.",Hunger:-4),new("Tenta un altro richiamo","Il velo si agita, ma non risponde.",Mind:-5)],"Quella notte, Roderick sogna un santuario che non ha mai visitato."),
        _=>new([new("NARRATORE","Nel sogno, ogni arco conduceva a un altro arco. Roderick non sapeva da quanto tempo stesse camminando."),new("NYARLATOTH","Hai visto un corridoio dove non ce n'era uno. Hai udito una creatura che non parlava. E ancora chiedi una spiegazione."),new("RODERICK","Voglio sapere se sono io a immaginare tutto questo."),new("NYARLATOTH","Non ti prometto risposte. Ti offro soltanto altri occhi con cui cercarle.")], ["Le geometrie si piegano verso di te. Il marchio di Nyarlatoth rende più forte il tuo richiamo.","Stringi il medaglione. Ritrovi il ricordo di un mondo che conosci.","Attraversi l'arco senza rispondere. Nulla ti segue."],"NYARLATOTH","Ci rivedremo quando non saprai più distinguere il sogno dalla veglia.",[],"Al risveglio, Roderick prende il treno per Dùsterbedragna. Il sogno non lo ha lasciato." )};
    public static Scene Resolve(GameRules g,int chapter){
        var scene=Get(g.State.Hero,chapter);var f=g.State.StoryFlags;
        if(g.State.Hero==HeroId.Gladia&&chapter==0&&f.Contains("gladia_origin_choice_0_option_4"))return scene with {FollowSpeaker="NARRATORE",FollowQuestion="Ti sei allontanata. La voce della bambina ti segue ancora nel vicolo.",Replies=[new("Torna sui tuoi passi","La famiglia non è più lì.",Hunger:-4),new("Continua la visita","Ti incammini verso la casa della malata."),new("Cerca di non pensarci","Non riesci a liberarti di quel ricordo.",Mind:-3)]};
        if(g.State.Hero==HeroId.Roderick&&chapter==0&&f.Contains("roderick_origin_choice_0_option_3"))return scene with {Replies=[scene.Replies[0],scene.Replies[1],new("Raccogli i resti delle carte","Le pagine sono ormai illeggibili.",Hunger:-3)]};
        if(g.State.Hero==HeroId.Roderick&&chapter==1&&(f.Contains("roderick_origin_choice_1_option_3")||f.Contains("roderick_origin_choice_1_option_4")))return scene with {FollowQuestion="Il cortile è ormai alle tue spalle. Cosa fai di quel ricordo?",Replies=[new("Non tornare indietro","Prosegui senza cercare la creatura."),new("Controlla le tracce","Le impronte scompaiono nel fango.",Hunger:-4),new("Tenta un ultimo richiamo","Il velo non risponde.",Mind:-5)]};
        return scene;}
    public static bool Apply(GameRules g,int chapter,int index){if(chapter<0||chapter>2)return false;var s=g.State;var options=Resolve(g,chapter).Replies;if(index<0||index>=options.Length)return false;string key=$"{s.Hero.ToString().ToLowerInvariant()}_origin_follow_{chapter}";if(!s.StoryFlags.Add(key))return false;s.StoryFlags.Add($"{key}_option_{index+1}");var r=options[index];s.Body=Math.Clamp(s.Body+r.Body,1,100);s.Mind=Math.Clamp(s.Mind+r.Mind,0,100);s.Hunger=Math.Clamp(s.Hunger+r.Hunger,0,100);if(r.Item!=null&&r.Quantity<0)s.Inventory[r.Item]=Math.Max(0,s.Inventory.GetValueOrDefault(r.Item,0)+r.Quantity);return true;}
}
